<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="auth-wrap"><a class="brand" href="/">c0m.me</a><section class="auth-card"><span class="eyebrow">ACCOUNT CENTER</span><h1>Create your account</h1><p>Join the c0m.me ecosystem with one secure account.</p><?php if (!empty($error)): ?><div class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if (!$registrationEnabled): ?><p>Registration is currently closed. Please check back later.</p><?php else: ?><form method="post" action="/register"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><label>Display name</label><input name="display_name" maxlength="100" autocomplete="name" required><label>Email address</label><input type="email" name="email" maxlength="190" autocomplete="email" required><label>Password</label><input type="password" name="password" minlength="12" autocomplete="new-password" required><small>At least 12 characters, including uppercase, lowercase and a number.</small><button class="button full" type="submit">Create account</button></form><?php endif; ?><small>Already have an account? <a href="/login">Sign in</a></small></section></main></body></html>
